using Marketplace.Domain.Common; namespace Marketplace.Domain.Payments; public sealed class Payment:AggregateRoot<long>{private Payment(){}public long OrderId{get;private set;}public long PaymentAttemptId{get;private set;}public long AmountIRR{get;private set;}public string CurrencyCode{get;private set;}=null!;public decimal FxRateToIRR{get;private set;}public string Gateway{get;private set;}=null!;public string GatewayTransactionId{get;private set;}=null!;public DateTime PaidAtUtc{get;private set;}public static Payment Create(long id,long orderId,long attemptId,long amount,string currency,decimal fx,string gateway,string tx,DateTime paidAtUtc){if(amount<=0||fx<=0||string.IsNullOrWhiteSpace(tx))throw new DomainException("Invalid payment.");return new(){Id=id,OrderId=orderId,PaymentAttemptId=attemptId,AmountIRR=amount,CurrencyCode=currency,Gateway=gateway,GatewayTransactionId=tx,PaidAtUtc=paidAtUtc};}}
